package com.paytrace.recovery;
import com.paytrace.decision.*; import com.paytrace.incident.*; import com.paytrace.payment.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class RecoveryPolicy { private final RecoveryRecommendationRepository repository; public RecoveryPolicy(RecoveryRecommendationRepository r){repository=r;}
 @Transactional public RecoveryRecommendation decide(PaymentView payment,List<Incident> incidents,DecisionAssessment decision){RecoveryAction action;String reason;if(incidents.stream().anyMatch(i->i.incidentType()==IncidentType.LEDGER_IMBALANCE||i.incidentType()==IncidentType.LEDGER_MISMATCH)){action=RecoveryAction.RECONCILE_LEDGER;reason="Ledger evidence failed an integrity invariant.";}else if(decision.manualReviewRequired()){action=RecoveryAction.MANUAL_REVIEW;reason="High-severity deterministic evidence requires operator review.";}else if(payment.canonicalState()==PaymentState.CAPTURED||payment.canonicalState()==PaymentState.SETTLED){action=RecoveryAction.DO_NOT_RETRY;reason="Canonical financial state has capture evidence; retry can create duplicate financial impact.";}else if(payment.canonicalState()==PaymentState.FAILED||payment.canonicalState()==PaymentState.CANCELLED){action=RecoveryAction.RETRY_SAFE;reason="No capture evidence is present and the terminal state is non-financial.";}else {action=RecoveryAction.REQUERY_PROVIDER;reason="Financial outcome remains incomplete; verify provider state before any retry.";}var r=new RecoveryRecommendation(UUID.randomUUID(),payment.paymentId(),action,reason,Instant.now());repository.save(new RecoveryRecommendationEntity(r));return r;}
 public Optional<RecoveryRecommendation> latest(UUID paymentId){return repository.findTop1ByPaymentIdOrderByCreatedAtDesc(paymentId).stream().findFirst().map(RecoveryRecommendationEntity::view);}
}
